#!/usr/bin/env bash
# =============================================================================
# TEST split — scene metadata generation
# =============================================================================
# 1 object per scene, 2 views, exactly one factor of variation per dataset:
#
#   camera_movement  — camera moves between views, object stays fixed
#   object_movement  — object moves between views, camera stays fixed
#
# Both are generated by default, into the directories named in config.yaml.
# Pass mode names to build only some of them, and any other argument is
# forwarded to distribute_generate.py:
#
#     ./scripts/generate_test.sh                              # both
#     ./scripts/generate_test.sh object_movement              # just one
#     ./scripts/generate_test.sh --global-count 20            # quick test
# =============================================================================

set -euo pipefail
cd "$(dirname "$0")/.."

modes=()
passthrough=()
for arg in "$@"; do
    case "$arg" in
        camera_movement|object_movement) modes+=("$arg") ;;
        *) passthrough+=("$arg") ;;
    esac
done
[[ ${#modes[@]} -eq 0 ]] && modes=(camera_movement object_movement)

for mode in "${modes[@]}"; do
    echo
    echo "=== generating test split: $mode ==="
    python3 pipelines/distribute_generate.py --split test --mode "$mode" \
        ${passthrough[@]+"${passthrough[@]}"}
done
